    },
    {
      "goal": "查期刊与分区指标",
      "entry": "期刊搜索",
      "boundary": "独立期刊目录，不应由智能搜索替代"
    },
    {
      "goal": "问答、读附件、做研究任务",
      "entry": "智能助手",
      "boundary": "通用研究助手，结果仍需核验来源"
    },
    {
      "goal": "编辑论文项目",
      "entry": "智能写作",
      "boundary": "面向 LaTeX 项目和变更确认"
    },
    {
      "goal": "投稿前预审",
      "entry": "智能审稿",
